const GENERIC_ENEMY_NAMES = {
  'Ferengi Alliance': ['Ferengi Marauder', 'Ferengi Interceptor', 'Ferengi Dreadnought'],
  'Breen Confederacy': ['Breen Raider', 'Breen Interceptor', 'Breen Cruiser'],
  'Tholian Assembly': ['Tholian Raider', 'Tholian Interceptor', 'Tholian Cruiser'],
  'Gorn Hegemony': ['Gorn Raider', 'Gorn Interceptor', 'Gorn Cruiser'],
  'Tzenkethi Coalition': ['Tzenkethi Raider', 'Tzenkethi Interceptor', 'Tzenkethi Cruiser'],
  'Dominion': ['Jem\'Hadar Fighter', 'Jem\'Hadar Attack Ship', 'Jem\'Hadar Battlecruiser'],
};

// Resolve the hostile order of battle for the current sector. A 2372 setting
// means Klingon ships are the default in Federation space (open war), while
// the Badlands/DMZ are Cardassian and the wormhole is Dominion.
export function enemyProfileFor(power, areaName = '') {
  if (power === 'United Federation of Planets') return ENEMY_SHIPS['Klingon Empire'];
  if (power === 'Contested Space') {
    if (/Badlands|Demilitarized|Setlik/i.test(areaName)) return ENEMY_SHIPS['Cardassian Union'];
    if (/Wormhole/i.test(areaName)) {
      const names = GENERIC_ENEMY_NAMES.Dominion;
      return genericProfile(names, 0x9a7cff, 0x9a7cff);
    }
    return ENEMY_SHIPS['Klingon Empire'];
  }
  if (ENEMY_SHIPS[power]) return ENEMY_SHIPS[power];
  const names = GENERIC_ENEMY_NAMES[power] || ['Raider', 'Interceptor', 'Gunship'];
  return genericProfile(names, 0xffb040, 0xffb060);
}

function genericProfile(names, bolt, engine) {
  return {
    raider: { model: null, name: names[0], bolt, engine, standoff: 0 },
    interceptor: { model: null, name: names[1], bolt, engine, standoff: 0 },
    gunship: { model: null, name: names[2], bolt, engine, standoff: 320 },
  };
}
